CREATE TABLE sku_stock(sku_id BIGINT PRIMARY KEY,available INT NOT NULL DEFAULT 0,reserved INT NOT NULL DEFAULT 0,updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),CHECK(available>=0),CHECK(reserved>=0),FOREIGN KEY(sku_id) REFERENCES product_sku(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE stock_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,business_type VARCHAR(32) NOT NULL,business_no VARCHAR(100) NOT NULL,sku_id BIGINT NOT NULL,quantity INT NOT NULL,before_available INT NOT NULL,before_reserved INT NOT NULL,after_available INT NOT NULL,after_reserved INT NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE(business_type,business_no,sku_id),FOREIGN KEY(sku_id) REFERENCES product_sku(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO sku_stock(sku_id,available,reserved) SELECT id,0,0 FROM product_sku;
